using System;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Drawing;
using System.Diagnostics;
using System.Windows.Forms;
namespace NoteNestSetup {
class Installer:Form {
 Button install=new Button();ProgressBar progress=new ProgressBar();CheckBox shortcut=new CheckBox();Label status=new Label();
 public Installer(){Text="NoteNest — Welcome home";ClientSize=new Size(560,430);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(250,248,240);var logo=new PictureBox{Bounds=new Rectangle(34,28,92,92),SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.Transparent};using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("NoteNest.logo")){using(var source=Image.FromStream(s))logo.Image=new Bitmap(source);}Controls.Add(logo);Controls.Add(new Label{Text="NoteNest",Font=new Font("Georgia",32),AutoSize=true,Location=new Point(145,36),ForeColor=Color.FromArgb(49,71,51)});Controls.Add(new Label{Text="A little room for your thoughts.",Font=new Font("Segoe UI",12),AutoSize=true,Location=new Point(149,88),ForeColor=Color.FromArgb(101,111,93)});Controls.Add(new Label{Text="Four cozy rooms. Four kinds of paper. Your own space.\n\nWrite a note, move it, finish it — and keep a private record\nin your own Google Drive when you choose to connect.\n\nInstalls for this Windows account. No administrator needed.\nNo Python, paid server or AI subscription required.",Font=new Font("Segoe UI",10),AutoSize=true,Location=new Point(38,146),ForeColor=Color.FromArgb(76,84,67)});shortcut.SetBounds(40,303,450,24);shortcut.Text="Add a desktop shortcut";shortcut.Checked=true;Controls.Add(shortcut);install.Text="Install NoteNest";install.SetBounds(322,350,194,42);install.BackColor=Color.FromArgb(53,77,57);install.ForeColor=Color.White;install.FlatStyle=FlatStyle.Flat;install.Click+=Install;Controls.Add(install);progress.SetBounds(40,355,260,8);Controls.Add(progress);status.SetBounds(40,373,270,40);status.Font=new Font("Segoe UI",8);Controls.Add(status);}
 void Install(object sender,EventArgs e){install.Enabled=false;try{string root=Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","NoteNest"));string allowed=Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs"))+Path.DirectorySeparatorChar;if(!root.StartsWith(allowed,StringComparison.OrdinalIgnoreCase))throw new Exception("Install path could not be verified.");if(Process.GetProcessesByName("NoteNest").Length>0)throw new Exception("Close NoteNest before updating it. Your notes will be kept.");Directory.CreateDirectory(root);using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("NoteNest.payload"))using(var zip=new ZipArchive(s,ZipArchiveMode.Read)){progress.Maximum=zip.Entries.Count;foreach(var entry in zip.Entries){string path=Path.GetFullPath(Path.Combine(root,entry.FullName));if(!path.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Invalid package path.");if(string.IsNullOrEmpty(entry.Name)){Directory.CreateDirectory(path);continue;}Directory.CreateDirectory(Path.GetDirectoryName(path));using(var input=entry.Open())using(var output=File.Create(path))input.CopyTo(output);progress.Value++;Application.DoEvents();}}if(shortcut.Checked){Type type=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(type);string desk=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);dynamic link=shell.CreateShortcut(Path.Combine(desk,"NoteNest.lnk"));link.TargetPath=Path.Combine(root,"NoteNest.exe");link.WorkingDirectory=root;link.IconLocation=Path.Combine(root,"NoteNest.ico");link.Description="Your own quiet note board";link.Save();}status.Text="Installed. Your empty board is ready.";install.Text="Open NoteNest";install.Enabled=true;install.Click-=Install;install.Click+=(a,b)=>{Process.Start(new ProcessStartInfo(Path.Combine(root,"NoteNest.exe")){WorkingDirectory=root,UseShellExecute=true});Close();};}catch(Exception ex){MessageBox.Show(this,ex.Message,"NoteNest",MessageBoxButtons.OK,MessageBoxIcon.Information);install.Enabled=true;}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Installer());}
}
}
